def check_depth(root):
    """Iterative container-nesting bound (root object is depth 1)."""
    order = [(root, 1)]
    while order:
        node, depth = order.pop()
        if depth > MAX_DEPTH:
            raise ValueError('invalid_request')
        if type(node) is dict:
            children = node.values()
        else:
            children = node
        child_depth = depth+1
        for child in children:
            if type(child) is dict or type(child) is list:
                order.append((child, child_depth))


